-- Catalogue scale (docs/SCALE.md): exact facet counts per category and brand
-- (product_facet_scope_counts, kept by the triggers below), the buyer-state
-- price indexes a large category or brand reads its price range and price
-- order through, and the price-list amount index a market's price order walks.
-- Generated by packages/database/scripts/catalog-scale-migration.ts.
CREATE TABLE "product_facet_scope_counts" (
	"scope_kind" text COLLATE "C" NOT NULL,
	"scope_id" text COLLATE "C" NOT NULL,
	"facet_kind" text COLLATE "C" NOT NULL,
	"facet_key" text COLLATE "C" NOT NULL,
	"value_key" text COLLATE "C" NOT NULL,
	"product_count" bigint NOT NULL,
	"sample_product_id" text COLLATE "C",
	PRIMARY KEY("scope_kind", "facet_kind", "scope_id", "facet_key", "value_key"),
	CONSTRAINT "product_facet_scope_counts_scope_kind" CHECK("product_facet_scope_counts"."scope_kind" IN ('category', 'brand')),
	CONSTRAINT "product_facet_scope_counts_kind" CHECK("product_facet_scope_counts"."facet_kind" IN ('attribute', 'option', 'brand', 'category', 'products', 'rating')),
	CONSTRAINT "product_facet_scope_counts_nonnegative" CHECK("product_facet_scope_counts"."product_count" >= 0)
);
