    AND NEW.owner_id = coalesce(NEW.variant_id, NEW.product_id)
    AND ((NEW.facet_kind = 'attribute' AND NEW.variant_id IS NULL)
      OR (NEW.facet_kind = 'option' AND NEW.variant_id IS NOT NULL AND substr(NEW.facet_key, 1, 7) = 'option.'))
    AND length(NEW.facet_key) BETWEEN 1 AND 120 AND length(NEW.value_key) BETWEEN 1 AND 200
    AND length(NEW.value_label) BETWEEN 1 AND 200 AND NOT EXISTS (SELECT 1 FROM product_facet_values f WHERE f.owner_id = NEW.owner_id AND f.facet_key = NEW.facet_key)), false) THEN
    RETURN NEW;
  END IF;
  INSERT INTO product_facet_scope_counts (scope_kind, scope_id, facet_kind, facet_key, value_key, product_count, sample_product_id)
    SELECT d.scope_kind, d.scope_id, d.facet_kind, d.facet_key, d.value_key,
      coalesce((SELECT c.product_count FROM product_facet_scope_counts c WHERE c.scope_kind = d.scope_kind AND c.scope_id = d.scope_id AND c.facet_kind = d.facet_kind AND c.facet_key = d.facet_key AND c.value_key = d.value_key), 0) + sum(d.delta),
      coalesce((SELECT c.sample_product_id FROM product_facet_scope_counts c WHERE c.scope_kind = d.scope_kind AND c.scope_id = d.scope_id AND c.facet_kind = d.facet_kind AND c.facet_key = d.facet_key AND c.value_key = d.value_key), NEW.product_id)
    FROM (SELECT scope.scope_kind, scope.scope_id, NEW.facet_kind AS facet_kind, NEW.facet_key AS facet_key, NEW.value_key AS value_key, 1 AS delta
    FROM (SELECT 'category' AS scope_kind, scope_buyer.category_id AS scope_id FROM product_buyer_state scope_buyer
      WHERE scope_buyer.product_id = NEW.product_id AND scope_buyer.is_public = 1 AND scope_buyer.category_id IS NOT NULL
      UNION ALL SELECT 'brand', scope_buyer.brand_id FROM product_buyer_state scope_buyer
      WHERE scope_buyer.product_id = NEW.product_id AND scope_buyer.is_public = 1 AND scope_buyer.brand_id IS NOT NULL) scope
    WHERE NOT EXISTS (
      SELECT 1 FROM product_facet_values sibling WHERE sibling.product_id = NEW.product_id
